import Synchronization

final class Account: Sendable {
    private let balance = Mutex<Int>(0)          // lock owns the value

    func deposit(_ amount: Int) {
        balance.withLock { $0 += amount }        // release on exit
    }
    func transfer(to other: Account, _ amount: Int) {
        balance.withLock { $0 -= amount }
        other.balance.withLock { $0 += amount }  // fixed lock order
    }
}
